def test_option_with_optional_value(runner, args, expect):
    @click.command()
    @click.option("-o", "--opt", is_flag=False, flag_value="flag")
    @click.option("-a")
    @click.argument("b", nargs=-1)
    def cli(opt, a, b):
        return opt, a, b

    result = runner.invoke(cli, args, standalone_mode=False, catch_exceptions=False)
    assert result.return_value == expect


def test_optional_value_with_default(runner):
    """An optional value may be omitted even when a default is configured."""

    @click.command()
    @click.option("--name", is_flag=False, flag_value="flag", default="default")
    def cli(name):
        return name

    assert runner.invoke(cli, [], standalone_mode=False).return_value == "default"
    assert runner.invoke(cli, ["--name"], standalone_mode=False).return_value == "flag"
    assert (
        runner.invoke(cli, ["--name", "Alice"], standalone_mode=False).return_value
        == "Alice"
    )


def test_optional_integer_value_with_default(runner):
    """Default and flag values are processed by the option's type."""

    @click.command()
    @click.option("--number", is_flag=False, flag_value=0, default=1, type=int)
    def cli(number):
        return number

    assert runner.invoke(cli, [], standalone_mode=False).return_value == 1
    assert runner.invoke(cli, ["--number"], standalone_mode=False).return_value == 0
    assert (
        runner.invoke(cli, ["--number", "42"], standalone_mode=False).return_value == 42
    )


def test_optional_value_invalid_type(runner):
    """Optional explicit values are still type checked."""

    @click.command()
    @click.option("--number", is_flag=False, flag_value=0, default=1, type=int)
    def cli(number):
        return number

    result = runner.invoke(cli, ["--number", "one"], standalone_mode=False)
    assert isinstance(result.exception, click.BadParameter)


def test_option_without_flag_value_still_requires_value(runner):
    """Only optional-value options may omit an explicit value."""

    @click.command()
    @click.option("--name", default="default")
    def cli(name):
        return name

    result = runner.invoke(cli, ["--name"], standalone_mode=False)
    assert isinstance(result.exception, click.BadOptionUsage)
    assert "requires an argument" in str(result.exception)

def test_multiple_option_with_optional_value(runner):
    cli = click.Command(
        "cli",
        params=[
            click.Option(["-f"], is_flag=False, flag_value="flag", multiple=True),
            click.Option(["-a"]),
            click.Argument(["b"], nargs=-1),
        ],
        callback=lambda **kwargs: kwargs,
        self.hide_input = hide_input
        self.hidden = hidden

        # The _flag_needs_value property tells the parser that this option is a flag
        # that cannot be used standalone and needs a value. With this information, the
        # parser can determine whether to consider the next user-provided argument in
        # the CLI as a value for this flag or as a new option.
        # If prompt is enabled but not required, then it opens the possibility for the
        # option to gets its value from the user.
        # An explicitly non-flag option with a flag value accepts either a value
        # written after the option, or no value at all. The latter is represented by
        # the FLAG_NEEDS_VALUE sentinel, which is replaced by ``flag_value`` below.
        self._flag_needs_value = (
            self.prompt is not None and not self.prompt_required
        ) or (is_flag is False and flag_value is not UNSET)

        # Auto-detect if this is a flag or not.
        if is_flag is None:
            # Implicitly a flag because flag_value was set.
            if flag_value is not UNSET:
                is_flag = True
